const RE_AC_HEADING = /acceptance criteria|crit[ée]rios de aceita[çc][ãa]o|crit[ée]rios de aceite|criterios de aceptaci[óo]n|(?<![\p{L}])EARS(?![\p{L}])|(?:^|\/ )US-\d+(?!\d)/iu;
