  // approval — earlier ones were overwritten), so their rework is unknown: `rework` is then a lower bound.
  const unseeded = history ? Object.keys(approvals).filter((ph) => isRecord(approvals[ph]) && !history.some((h) => h.phase === ph)) : [];
