  const F = i18n.msg(lang).forecast;
  const short = (d) => (d.slice(0, 4) === fc.eta.slice(0, 4) ? d.slice(5) : d);
  const [low, high] = Array.isArray(fc.range) ? fc.range : [fc.eta, fc.eta];
