  // A project path — not a [placeholder], a "TBD" / "n/a" / "none" / "-" stand-in, the project root or a path leaving it.
  const okKey = (k) => !!k && k !== "." && !/^\[.*\]$/.test(k) && !/^(?:tbd|todo|n\/?a|none|-+|…|\.{3})$/i.test(k) && !k.startsWith("/") && !/^[A-Za-z]:/.test(k) && !k.split("/").includes("..");
  let truncated = false;
