    const tests = [];
    for (const e of entries) {
      if (!cites(row, e.acs, e.sec)) continue;
      for (const id of e.ids) if (!tests.some((t) => tKey(t.id.slice(2)) === tKey(id.slice(2)))) tests.push({ id });
    }
