  if (f.doctor.failing.length) act(I.fix(f.doctor.failing.map((c) => c.id + (c.detail ? ` (${c.detail})` : "")).join("; ")));
  if (f.pendingGates.length) act(I.approve(f.pendingGates.join(", "), f.name));
